const menuToggle = document.getElementById('menu-toggle');const nav = document.getElementById('nav');menuToggle.addEventListener('click',() =>{nav.classList.toggle('active');});let slideIndex = 0;const slides = document.querySelectorAll('.slide');const dots = document.querySelectorAll('.dot');function showSlide(index){slides.forEach((slide,i) =>{slide.classList.remove('active');dots[i].classList.remove('active');});slides[index].classList.add('active');dots[index].classList.add('active');slideIndex = index;}function nextSlide(){slideIndex = (slideIndex + 1) % slides.length;showSlide(slideIndex);}function currentSlide(index){showSlide(index);}setInterval(nextSlide,5000);document.addEventListener('DOMContentLoaded',function(){const depoimentos = document.querySelectorAll('.depoimento-card');const dots = document.querySelectorAll('.depoimento-dot');let currentIndex = 0;function showDepoimento(index){depoimentos.forEach(depoimento =>{depoimento.style.display = 'none';});dots.forEach(dot =>{dot.classList.remove('active');});depoimentos[index].style.display = 'block';dots[index].classList.add('active');currentIndex = index;}showDepoimento(0);dots.forEach((dot,index) =>{dot.addEventListener('click',() =>{showDepoimento(index);});});function nextDepoimento(){currentIndex = (currentIndex + 1) % depoimentos.length;showDepoimento(currentIndex);}setInterval(nextDepoimento,5000);});document.addEventListener('DOMContentLoaded',function(){const menuItems = document.querySelectorAll('.menu-item');menuItems.forEach(item =>{item.addEventListener('click',function(){menuItems.forEach(i => i.classList.remove('active'));this.classList.add('active');const serviceId = this.getAttribute('data-service');document.querySelectorAll('.service-content').forEach(content =>{content.classList.remove('active');});document.getElementById(serviceId).classList.add('active');});});});document.addEventListener('DOMContentLoaded',function(){const emergencyButtons = document.querySelectorAll('.emergency-button');emergencyButtons.forEach(button =>{button.addEventListener('click',function(e){this.classList.add('clicked');setTimeout(() =>{this.classList.remove('clicked');},300);logEmergencyContact(this.getAttribute('href'));});});function logEmergencyContact(phoneNumber){console.log('Contato de emergência solicitado:',phoneNumber);}const emergencyCards = document.querySelectorAll('.emergency-card');const observerOptions ={threshold:0.1,rootMargin:'0px 0px -100px 0px'};const observer = new IntersectionObserver(function(entries,observer){entries.forEach(entry =>{if (entry.isIntersecting){entry.target.classList.add('animate__animated','animate__fadeInUp');observer.unobserve(entry.target);}});},observerOptions);emergencyCards.forEach(card =>{observer.observe(card);});const coverageItems = document.querySelectorAll('.coverage-list li');coverageItems.forEach(item =>{item.addEventListener('mouseenter',function(){this.style.backgroundColor = '#e74c3c';this.style.color = '#fff';this.style.transform = 'scale(1.05)';this.style.transition = 'all 0.3s ease';});item.addEventListener('mouseleave',function(){this.style.backgroundColor = '#f1f1f1';this.style.color = '#333';this.style.transform = 'scale(1)';});});const phoneNumbers = document.querySelectorAll('.phone-number');function pulsePhones(){phoneNumbers.forEach((phone,index) =>{setTimeout(() =>{phone.classList.add('animate__animated','animate__pulse');setTimeout(() =>{phone.classList.remove('animate__animated','animate__pulse');},1000);},index * 1000);});}pulsePhones();setInterval(pulsePhones,15000);const style = document.createElement('style');style.textContent = ` .emergency-button.clicked{transform:scale(0.95);transition:transform 0.2s ease;}.phone-number{position:relative;}@keyframes pulse{0%{transform:scale(1);}50%{transform:scale(1.05);}100%{transform:scale(1);}}`;document.head.appendChild(style);});document.addEventListener('DOMContentLoaded',function(){const benefitItems = document.querySelectorAll('.benefit-item');const observerOptions ={threshold:0.2,rootMargin:'0px 0px -50px 0px'};const benefitObserver = new IntersectionObserver(function(entries,observer){entries.forEach((entry,index) =>{if (entry.isIntersecting){setTimeout(() =>{entry.target.classList.add('animate__animated','animate__fadeInUp');},index * 100);observer.unobserve(entry.target);}});},observerOptions);benefitItems.forEach(item =>{benefitObserver.observe(item);});const planCards = document.querySelectorAll('.plan-card');const planObserver = new IntersectionObserver(function(entries,observer){entries.forEach((entry,index) =>{if (entry.isIntersecting){setTimeout(() =>{entry.target.classList.add('animate__animated','animate__zoomIn');},index * 200);observer.unobserve(entry.target);}});},observerOptions);planCards.forEach(card =>{planObserver.observe(card);});planCards.forEach(card =>{card.addEventListener('mouseenter',function(){if (!this.classList.contains('featured')){this.style.transform = 'translateY(-10px)';this.style.boxShadow = '0 8px 25px rgba(0,0,0,0.15)';}else{this.style.transform = 'scale(1.05) translateY(-10px)';}});card.addEventListener('mouseleave',function(){if (!this.classList.contains('featured')){this.style.transform = '';this.style.boxShadow = '';}else{this.style.transform = 'scale(1.05)';}});});const scheduleRows = document.querySelectorAll('.schedule-row');const scheduleObserver = new IntersectionObserver(function(entries,observer){entries.forEach((entry,index) =>{if (entry.isIntersecting){setTimeout(() =>{entry.target.classList.add('animate__animated','animate__fadeInLeft');},index * 100);observer.unobserve(entry.target);}});},observerOptions);scheduleRows.forEach(row =>{scheduleObserver.observe(row);});const fleetCta = document.querySelector('.fleet-cta');const ctaObserver = new IntersectionObserver(function(entries,observer){entries.forEach(entry =>{if (entry.isIntersecting){entry.target.classList.add('animate__animated','animate__fadeIn');observer.unobserve(entry.target);}});},{threshold:0.3});if (fleetCta){ctaObserver.observe(fleetCta);}const ctaButtons = document.querySelectorAll('.cta-button,.plan-button');ctaButtons.forEach(button =>{button.addEventListener('click',function(e){if (this.getAttribute('href') === '#contato'){e.preventDefault();const contatoSection = document.querySelector('#contato') || document.querySelector('.quote-section');if (contatoSection){contatoSection.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(() =>{contatoSection.classList.add('highlight-section');setTimeout(() =>{contatoSection.classList.remove('highlight-section');},1500);},800);}}});});const style = document.createElement('style');style.textContent = ` @keyframes highlightPulse{0%{box-shadow:0 0 0 0 rgba(231,76,60,0.7);}70%{box-shadow:0 0 0 20px rgba(231,76,60,0);}100%{box-shadow:0 0 0 0 rgba(231,76,60,0);}}.highlight-section{animation:highlightPulse 1.5s ease;}.animate__fadeInUp{animation:fadeInUp 0.6s ease forwards;}.animate__fadeInLeft{animation:fadeInLeft 0.6s ease forwards;}.animate__zoomIn{animation:zoomIn 0.6s ease forwards;}.animate__fadeIn{animation:fadeIn 0.8s ease forwards;}@keyframes fadeInUp{from{opacity:0;transform:translate3d(0,30px,0);}to{opacity:1;transform:translate3d(0,0,0);}}@keyframes fadeInLeft{from{opacity:0;transform:translate3d(-30px,0,0);}to{opacity:1;transform:translate3d(0,0,0);}}@keyframes zoomIn{from{opacity:0;transform:scale3d(0.3,0.3,0.3);}50%{opacity:1;}}@keyframes fadeIn{from{opacity:0;}to{opacity:1;}}`;document.head.appendChild(style);});(function(){function loadAnalytics(){if(window._cookieAnalyticsLoaded)return;window._cookieAnalyticsLoaded=true;window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments);};var gtagScript=document.createElement('script');gtagScript.async=true;gtagScript.src='https://www.googletagmanager.com/gtag/js?id=AW-16641003711';gtagScript.onload=function(){window.gtag('js',new Date());window.gtag('config','AW-16641003711');};document.head.appendChild(gtagScript);var gtmScript=document.createElement('script');gtmScript.text="(function(w,d,s,l,i){w[l]=w[l]||[];w[l].push({'gtm.start':new Date().getTime(),event:'gtm.js'});var f=d.getElementsByTagName(s)[0],j=d.createElement(s),dl=l!='dataLayer'?'&l='+l:'';j.async=true;j.src='https://www.googletagmanager.com/gtm.js?id='+i+dl;f.parentNode.insertBefore(j,f);})(window,document,'script','dataLayer','GTM-58TL9BJ2');";document.head.appendChild(gtmScript);}function removeCookieBanner(){var b=document.querySelector('.cookie-banner');if(b)b.remove();}function acceptCookies(){localStorage.setItem('cookieConsent','accepted');removeCookieBanner();loadAnalytics();}function declineCookies(){localStorage.setItem('cookieConsent','declined');removeCookieBanner();}function createCookieBanner(){if(document.querySelector('.cookie-banner'))return;var b=document.createElement('div');b.className='cookie-banner';b.innerHTML='<div class="cookie-banner-inner"><div class="cookie-banner-text"><strong>Usamos cookies</strong> para melhorar sua experiência. <a href="privacidade.html">Leia nossa política de privacidade</a>.</div><div class="cookie-banner-actions"><button type="button" id="cookie-accept">Aceitar</button><button type="button" id="cookie-decline">Recusar</button></div></div>';document.body.appendChild(b);document.getElementById('cookie-accept').addEventListener('click',acceptCookies);document.getElementById('cookie-decline').addEventListener('click',declineCookies);}function initCookieConsent(){var consent=localStorage.getItem('cookieConsent');if(consent==='accepted'){loadAnalytics();}else if(consent==='declined'){return;}else{createCookieBanner();}}document.addEventListener('DOMContentLoaded',initCookieConsent);}());